class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        visited = []
        for row in range(len(grid)):
            cols = list(range(len(grid[0])))
            if row % 2 == 1:
                cols.reverse()
            for col in cols:
                visited.append(grid[row][col])
        return visited[::2]

