class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(2, n + 1):
            fact[i] = fact[i - 1] * i

        odd = (n + 1) // 2
        even = n // 2

        if n % 2 == 0:
            total = 2 * fact[n // 2] * fact[n // 2]
        else:
            total = fact[odd] * fact[even]

        if k > total:
            return []

        def count_ways(rO: int, rE: int, next_parity) -> int:
            length = rO + rE
            if length == 0:
                return 1

            ceil_len = (length + 1) // 2
            floor_len = length // 2

            if next_parity == 'O':
                if rO == ceil_len and rE == floor_len:
                    return fact[rO] * fact[rE]
                return 0
            else:  # next_parity == 'E'
                if rE == ceil_len and rO == floor_len:
                    return fact[rO] * fact[rE]
                return 0

        used = [False] * (n + 1)
        rO, rE = odd, even
        prev_parity = None
        answer = []

        for i in range(1, n + 1):
            if i == 1:
                required = None
            else:
                required = 'E' if prev_parity == 'O' else 'O'

            chosen = False
            for v in range(1, n + 1):
                if used[v]:
                    continue

                parity = 'O' if v % 2 == 1 else 'E'
                if required is not None and parity != required:
                    continue

                if parity == 'O':
                    nrO, nrE = rO - 1, rE
                    next_parity = 'E' if i < n else None
                else:
                    nrO, nrE = rO, rE - 1
                    next_parity = 'O' if i < n else None

                cnt = count_ways(nrO, nrE, next_parity)

                if k > cnt:
                    k -= cnt
                else:
                    answer.append(v)
                    used[v] = True
                    rO, rE = nrO, nrE
                    prev_parity = parity
                    chosen = True
                    break

            if not chosen:
                return []

        return answer
